using System.Reflection;
using System.Text;

namespace RoslynSentinel.Server.Advanced;

/// <summary>Renders the declared startup settings as a markdown reference and as console text.</summary>
public static class ConfigurationReferenceRenderer
{
    // The generated text always uses "\n" (never Environment.NewLine) so a freshness test can compare file equality on any platform.
    private const string Nl = "\n";

    private const string MarkdownHeader =
        "<!-- Generated by ConfigurationReferenceRenderer; DO NOT EDIT. Regenerate with: $env:ROSLYNSENTINEL_UPDATE_GENERATED_DOCS=1; scripts/Generate-ArchitectureMap.ps1 -->";

    public static string RenderMarkdown(IReadOnlyList<StartupSetting> settings)
    {
        var sb = new StringBuilder();
        sb.Append(MarkdownHeader).Append(Nl).Append(Nl);
        sb.Append("# Configuration reference").Append(Nl).Append(Nl);
        sb.Append("A new setting is declared as a `StartupSetting.*` field in a `[StartupSettingGroup]` class. ")
            .Append("The tables list declared defaults, never effective values; for the effective values call McpServerStatus with `settings`.")
            .Append(Nl).Append(Nl);
        sb.Append("Shipped toolset JSON files are documented in [toolsets/](toolsets/).").Append(Nl);

        foreach (var (title, group) in GroupSettings(settings))
        {
            sb.Append(Nl).Append("## ").Append(EscapeCell(title)).Append(Nl).Append(Nl);
            sb.Append("| Setting | Flag | Env | Type | Default | Scope | Kind | Description |").Append(Nl);
            sb.Append("| --- | --- | --- | --- | --- | --- | --- | --- |").Append(Nl);
            foreach (var s in group)
            {
                sb.Append("| ").Append(EscapeCell(s.Name))
                    .Append(" | ").Append(Code(s.Flag))
                    .Append(" | ").Append(Code(s.EnvName))
                    .Append(" | ").Append(EscapeCell(FriendlyTypeName(s.ValueType)))
                    .Append(" | ").Append(Code(s.DefaultText))
                    .Append(" | ").Append(EscapeCell(s.Scope.ToString()))
                    .Append(" | ").Append(EscapeCell(s.Kind.ToString()))
                    .Append(" | ").Append(EscapeCell(s.Description))
                    .Append(" |").Append(Nl);
            }
        }

        return sb.ToString();
    }

    public static string RenderConsole(IReadOnlyList<StartupSetting> settings)
    {
        var lines = new List<string>();
        foreach (var (_, group) in GroupSettings(settings))
        {
            foreach (var s in group)
            {
                var id = s.Flag is not null && s.EnvName is not null ? $"{s.Flag}, {s.EnvName}" : s.Flag ?? s.EnvName ?? s.Name;
                lines.Add($"{id}  {FriendlyTypeName(s.ValueType)}  default {s.DefaultText}  {OneLine(s.Description)}");
            }
        }

        return string.Join(Nl, lines);
    }

    // Groups by declaring class, ordered by the group's lowest scope flag value, then title (class name as the final tie-break).
    // Settings inside a group are ordered by Name so the output does not depend on reflection order.
    private static List<(string Title, List<StartupSetting> Settings)> GroupSettings(IReadOnlyList<StartupSetting> settings)
    {
        var titles = ResolveGroupTitles();
        return settings
            .GroupBy(s => ClassOf(s.Name), StringComparer.Ordinal)
            .Select(g => (
                ClassName: g.Key,
                Title: titles.TryGetValue(g.Key, out var title) ? title : g.Key,
                ScopeKey: g.Min(s => LowestFlag(s.Scope)),
                Settings: g.OrderBy(s => s.Name, StringComparer.Ordinal).ToList()))
            .OrderBy(g => g.ScopeKey)
            .ThenBy(g => g.Title, StringComparer.Ordinal)
            .ThenBy(g => g.ClassName, StringComparer.Ordinal)
            .Select(g => (g.Title, g.Settings))
            .ToList();
    }

    // StartupSetting carries no group property: the class part of Name is matched against [StartupSettingGroup] types in the loaded
    // RoslynSentinel.* assemblies. Built once per render call; an unresolved class name falls back to the class name as the title.
    private static Dictionary<string, string> ResolveGroupTitles()
    {
        var titles = new Dictionary<string, string>(StringComparer.Ordinal);
        var assemblies = AppDomain.CurrentDomain.GetAssemblies()
            .Where(a => a.GetName().Name?.StartsWith("RoslynSentinel", StringComparison.Ordinal) == true)
            .OrderBy(a => a.GetName().Name, StringComparer.Ordinal);
        foreach (var assembly in assemblies)
        {
            Type?[] types;
            try
            {
                types = assembly.GetTypes();
            }
            catch (ReflectionTypeLoadException ex)
            {
                types = ex.Types;
            }

            foreach (var type in types.Where(t => t is not null).OrderBy(t => t!.FullName, StringComparer.Ordinal))
            {
                var attribute = type!.GetCustomAttribute<StartupSettingGroupAttribute>();
                if (attribute is not null)
                {
                    titles.TryAdd(type.Name, attribute.Title);
                }
            }
        }

        return titles;
    }

    private static string ClassOf(string name)
    {
        var dot = name.IndexOf('.');
        return dot < 0 ? name : name[..dot];
    }

    private static int LowestFlag(SettingScope scope)
    {
        var value = (int)scope;
        return value == 0 ? int.MaxValue : value & -value;
    }

    private static string FriendlyTypeName(Type type)
    {
        var underlying = Nullable.GetUnderlyingType(type);
        if (underlying is not null)
        {
            return FriendlyTypeName(underlying) + "?";
        }

        if (type == typeof(bool)) return "bool";
        if (type == typeof(int)) return "int";
        if (type == typeof(double)) return "double";
        if (type == typeof(string)) return "string";
        return type.Name;
    }

    private static string Code(string? text) => string.IsNullOrEmpty(text) ? string.Empty : "`" + EscapeCell(text) + "`";

    private static string OneLine(string text) => text.Replace("\r\n", " ").Replace('\n', ' ').Replace('\r', ' ');

    private static string EscapeCell(string text) => OneLine(text).Replace("|", "\\|");
}
